import {inventoryAction,transferPreview,nearbyRecipients,nearbyLoot,itemName} from './battle-inventory.js';
import {carryCapacity,loadMultiplier} from './inventory-tools.js';
import {pileOpen,searchPreview} from './core/engine.js';
import {WEAPONS,canControl,combatCosts} from './core/engine.js';
import {gridEntries,gridLayout,loadWeight} from './core/inventory.js';
import {characterArt} from './character-art.js';
import {inventoryArt} from './loot-art.js';
export {STAT_DEFINITIONS as CHARACTER_STATS} from './character-stats.js';
import {STAT_DEFINITIONS as CHARACTER_STATS} from './character-stats.js';
const bounded=v=>Number.isFinite(v)?Math.max(1,Math.min(100,Math.round(v))):null;
export function characterSheet(u,{equipmentState='carried'}={}){
 const legacy={medical:u.medical,perception:u.perception,sneak:u.stealth},stats=CHARACTER_STATS.map(([key,label])=>({key,label,value:bounded(u.stats?.[key]??legacy[key])}));
 const equipment=(u.slots||[]).filter(Boolean).map(kind=>({type:kind==='wireCutters'?'utility':'weapon',kind,held:kind===u.weapon,stowed:kind===u.weapon&&equipmentState==='stowed',drawing:kind===u.weapon&&equipmentState==='drawing',rounds:u.ammo?.[kind]}));
 if(u.weapon==='hands')equipment.unshift({type:'weapon',kind:'hands',held:true});
 const layout=gridLayout(u),backpack=gridEntries(u).map(e=>({...e,cell:layout.entries.find(p=>p.key===e.key)?.cell}));
 return {name:u.name,species:u.species,portrait:characterArt(u.species,'hands').src,stats,equipment,backpack,weight:loadWeight(u),hp:u.hp,maxHp:u.maxHp,ap:u.ap,maxAp:u.maxAp,stamina:u.stamina,maxStamina:u.maxStamina,damageResistance:u.damageResistance,carryCapacity:carryCapacity(u),loadMultiplier:loadMultiplier(u,loadWeight(u))};
}
const el=(tag,cls,text)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e;};
function itemCard(item){const name=itemName(item),label=item.type==='ammo'?name+' ammunition':name,card=el('div','dossier-item'),src=inventoryArt(item);if(src){const image=el('img');image.src=src;image.alt='';card.append(image);}else card.append(el('span','item-symbol',item.kind==='hands'?'✊':'◆'));card.append(el('strong','',label));const details=item.held?(item.stowed?'Stowed':item.drawing?'Drawing':'In hand'):item.type==='ammo'||item.count?'Quantity: '+item.count:item.type==='weapon'&&WEAPONS[item.kind]?.mag?'Loaded: '+(item.rounds??0):'Ready';card.append(el('small','',details));if(item.held&&WEAPONS[item.kind]?.mag)card.append(el('small','','Loaded: '+(item.rounds??0)));return card;}
export function createCharacterScreen({getState,onOpen,onClose,getEquipmentState=()=> 'carried',onEquip,canEquip=()=>true,onInventoryChange}){
 const dialog=el('dialog','character-dossier');dialog.id='character-screen';dialog.setAttribute('aria-labelledby','character-name');document.body.append(dialog);let unitId,inventoryNotice='';
 function render(){const state=getState(),roster=state.units.filter(u=>u.team==='squad'),u=roster.find(u=>u.id===unitId)||roster[0];if(!u)return;unitId=u.id;const sheet=characterSheet(u,{equipmentState:getEquipmentState(u.id)});dialog.replaceChildren();
  const top=el('div','dossier-top'),label=el('span','','Personnel / Field record'),close=el('button','','Close ×');close.id='character-close';close.onclick=()=>dialog.close();top.append(label,close);
  const nav=el('nav','dossier-roster');nav.setAttribute('aria-label','Squad character records');for(const merc of roster){const button=el('button','',merc.name);button.setAttribute('aria-pressed',String(merc.id===unitId));button.onclick=()=>{unitId=merc.id;render();dialog.querySelector('[aria-pressed="true"]').focus();};nav.append(button);}
  const body=el('div','dossier-body'),identity=el('section','dossier-identity'),portrait=el('img','dossier-portrait');portrait.src=sheet.portrait;portrait.alt=sheet.species+' sprite portrait';const name=el('h2','',sheet.name);name.id='character-name';identity.append(el('p','dossier-kicker','Animal Factory / Mercenary'),name,el('p','',sheet.species.replaceAll('-',' ')+' · '+(u.casualty||'Active')),portrait);
  const resources=el('dl','dossier-resources');for(const [key,value]of [['Damage resistance',Number.isFinite(sheet.damageResistance)?'-'+sheet.damageResistance+' / hit':'—'],['Health',sheet.hp+' / '+sheet.maxHp],['Action points',sheet.ap+' / '+sheet.maxAp],['Stamina',Number.isFinite(sheet.maxStamina)?Math.floor(sheet.stamina??sheet.maxStamina)+' / '+sheet.maxStamina:'—']])resources.append(el('dt','',key),el('dd','',value));identity.append(resources);
  const stats=el('section','dossier-stats');stats.append(el('h3','','Attributes & skills'),el('p','dossier-kicker','Scale 1–100'));const list=el('dl','stat-list');for(const stat of sheet.stats){const row=el('div','stat-row');row.append(el('dt','',stat.label),el('dd','',stat.value??'—'));const meter=el('div','stat-meter');meter.style.setProperty('--stat',String(stat.value??0)+'%');meter.setAttribute('aria-hidden','true');row.append(meter);list.append(row);}stats.append(list);if(sheet.stats.some(s=>s.value===null)||!Number.isFinite(sheet.maxStamina))stats.append(el('p','dossier-note','— Not assigned yet. Health and AP show current battle values.'));
  const runInventory=a=>{if(!canEquip(u))return;const oldWeapon=u.weapon;if(inventoryAction(state,u,a)){inventoryNotice='Equipment updated.';onInventoryChange?.();if(u.weapon!==oldWeapon){dialog.close();return;}}else inventoryNotice=(['take','give','drop'].includes(a.mode)?transferPreview(state,u,a).reason:null)||'Cannot move this item. Check backpack space, AP and the selected cell.';render();};
  const management=(card,item,key,slot)=>{if(!onInventoryChange||item.kind==='hands')return;const buttons=el('div','item-actions');const button=(label,a,preview)=>{const b=el('button','',label);b.disabled=!canControl(state,u)||!!state.queue.length||!canEquip(u)||preview?.ok===false;b.title=preview?.reason||'';b.onclick=()=>runInventory(a);buttons.append(b);};
   if(slot!==undefined)card.append(el('small','','Ready slot '+(slot+1)));
   if(slot!==undefined)button('To backpack',{mode:'stow',slot});else if(item.type==='weapon'||item.kind==='wireCutters')for(const slot of [0,1])button('Ready '+(slot+1)+(combatCosts(state)?' · 3 AP':''),{mode:'ready',key,slot});
   let quantity=item.type==='weapon'?1:item.count;const input=el('input');if(quantity>1){input.type='number';input.min=1;input.max=quantity;input.value=quantity;input.setAttribute('aria-label','Quantity of '+itemName(item));buttons.append(input);}const count=()=>quantity>1?Number(input.value):quantity;
   const drop=el('button','','Drop'+(combatCosts(state)?' · 2 AP':''));drop.disabled=!canControl(state,u)||!canEquip(u)||!!state.queue.length||!transferPreview(state,u,{mode:'drop',key}).ok;drop.onclick=()=>runInventory({mode:'drop',key,count:count()});buttons.append(drop);
   const recipients=nearbyRecipients(state,u);if(recipients.length){const select=el('select');select.setAttribute('aria-label','Give '+itemName(item)+' to');for(const v of recipients){const opt=el('option','',v.name);opt.value=v.id;select.append(opt);}const give=el('button','','Give'+(combatCosts(state)?' · 2 AP':''));give.disabled=drop.disabled;give.onclick=()=>runInventory({mode:'give',key,count:count(),target:state.units.find(v=>v.id===Number(select.value))});buttons.append(select,give);}
   if(slot===undefined){const cells=el('select');cells.setAttribute('aria-label','Backpack cell for '+itemName(item));for(let cell=0;cell<18;cell++){const opt=el('option','','Cell '+(cell+1));opt.value=cell;cells.append(opt);}cells.value=sheet.backpack.find(e=>e.key===key)?.cell??0;const place=el('button','','Move');place.disabled=!canControl(state,u)||!canEquip(u)||!!state.queue.length;place.onclick=()=>runInventory({mode:'arrange',key,cell:Number(cells.value)});buttons.append(cells,place);}
   card.append(buttons);
  };
  const gear=el('section','dossier-gear');const equipmentCard=item=>{const card=itemCard(item);if(onEquip&&item.type==='weapon'&&!item.held&&item.kind!==u.weapon){const cost=combatCosts(state)&&!u.slots.includes(item.kind)?3:0,draw=el('button','draw-weapon','Draw'+(cost?' · '+cost+' AP':''));draw.dataset.weapon=item.kind;draw.disabled=!canControl(state,u)||!!state.queue.length||!canEquip(u)||u.ap<cost;draw.onclick=()=>{if(onEquip(u.id,item.kind))dialog.close();else render();};card.append(draw);}return card;};gear.append(el('h3','','Held & ready equipment'));const equipped=el('div','dossier-equipment');for(const item of sheet.equipment){const card=equipmentCard(item),key=item.kind==='wireCutters'?'wireCutters':String(u.pack.findIndex(i=>i.type==='weapon'&&i.kind===item.kind));management(card,item,key,u.slots.indexOf(item.kind));equipped.append(card);}if(!sheet.equipment.length)equipped.append(el('p','','No equipment'));gear.append(equipped,el('h3','','Backpack'),el('p','dossier-kicker',sheet.weight.toFixed(1)+' / '+(Number.isFinite(sheet.carryCapacity)?sheet.carryCapacity.toFixed(1):'—')+' kg comfort load · '+sheet.loadMultiplier.toFixed(2)+'× movement stamina · 18 backpack cells'));
  const pack=el('div','dossier-backpack');for(const entry of sheet.backpack){const card=equipmentCard(entry.item);card.dataset.itemKey=entry.key;card.append(el('small','','Cell '+(entry.cell+1)+(entry.span>1?' · '+entry.span+' cells':'')));card.style.gridColumn='span '+entry.span;management(card,entry.item,entry.key);pack.append(card);}if(!sheet.backpack.length)pack.append(el('p','','Backpack empty'));gear.append(pack);if(inventoryNotice){const notice=el('p','dossier-note',inventoryNotice);notice.setAttribute('role','status');gear.append(notice);}if(onInventoryChange){gear.append(el('h3','','Nearby loot'));const loot=el('div','dossier-loot');for(const pile of nearbyLoot(state,u)){const section=el('section','dossier-item');section.append(el('strong','',pile.body===undefined?'Supplies':'Body'));if(!pileOpen(pile)){const search=el('button','','Search body'+(combatCosts(state)?' · 3 AP':''));const p=searchPreview(state,u,pile);search.disabled=!p.ok||!canEquip(u);search.title=p.reason;search.onclick=()=>runInventory({mode:'search',target:pile});section.append(search);}else for(const [index,item]of pile.items.entries()){const card=itemCard(item),a={mode:'take',target:pile,index},p=transferPreview(state,u,a),take=el('button','','Take'+(combatCosts(state)?' · 2 AP':''));take.disabled=!p.ok||!canEquip(u);take.title=p.reason;take.onclick=()=>runInventory(a);card.append(take);section.append(card);}loot.append(section);}if(!loot.childNodes.length)loot.append(el('p','','Move beside visible supplies or a body to collect equipment.'));gear.append(loot);}body.append(identity,stats,gear);dialog.append(top,nav,body);
 }
 dialog.addEventListener('close',()=>onClose?.());return {get open(){return dialog.open;},show(id){unitId=id;inventoryNotice='';render();dialog.showModal();onOpen?.();dialog.querySelector('#character-close').focus();}};
}
